using System.Linq;using NUnit.Framework;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
namespace Rootborn.Tests.EditMode.UI.StudentLife{public sealed class LibraryBookStationArtTests{
[SetUp]public void RequireSavedEditorState(){for(int i=0;i<UnityEngine.SceneManagement.SceneManager.sceneCount;i++)Assert.That(UnityEngine.SceneManagement.SceneManager.GetSceneAt(i).isDirty,Is.False,"Never discard unsaved scenes");EditorSceneManager.OpenScene("Assets/Scenes/Boot.unity",OpenSceneMode.Single);}
[Test]public void DedicatedSpriteRetainsCrispReviewedFloorPivot(){const string path="Assets/Art/UrbanStreet/Buildings31/library_book_station.png";var s=AssetDatabase.LoadAssetAtPath<Sprite>(path);Assert.That(s,Is.Not.Null);Assert.That(s.rect.size,Is.EqualTo(new Vector2(64,96)));Assert.That(s.pivot,Is.EqualTo(new Vector2(32,4)));Assert.That(s.pixelsPerUnit,Is.EqualTo(48));var i=(TextureImporter)AssetImporter.GetAtPath(path);Assert.That(i.filterMode,Is.EqualTo(FilterMode.Point));Assert.That(i.mipmapEnabled,Is.False);Assert.That(i.textureCompression,Is.EqualTo(TextureImporterCompression.Uncompressed));Assert.That(i.npotScale,Is.EqualTo(TextureImporterNPOTScale.None));var e=UnityEditor.AddressableAssets.AddressableAssetSettingsDefaultObject.Settings.FindAssetEntry(AssetDatabase.AssetPathToGUID(path));Assert.That(e,Is.Not.Null);Assert.That(e.address,Is.EqualTo("sprites/town/comfy31/library-book-station"));}
[Test]public void OnlyExistingLibraryVisitPointUsesDedicatedStation(){var scene=EditorSceneManager.OpenPreviewScene("Assets/Scenes/Town.unity");try{var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var root=all.Single(t=>t.name=="LocationVisit_location_library");var v=root.Find("Visual").GetComponent<SpriteRenderer>();Assert.That(v.sprite.name,Is.EqualTo("library_book_station"));Assert.That(root.GetComponent<Rootborn.Game.StudentLife.LocationActivityInteractor>(),Is.Not.Null);Assert.That(root.GetComponents<Collider2D>().Any(c=>c.isTrigger),Is.True);Assert.That(all.SelectMany(t=>t.GetComponents<SpriteRenderer>()).Count(r=>r.sprite!=null&&r.sprite.name=="library_book_station"),Is.EqualTo(1),"Dedicated station is not a global replacement for classroom bookcases");Assert.That(AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Art/SchoolPixels/sprites/bookcase.png"),Is.Not.Null);}finally{EditorSceneManager.ClosePreviewScene(scene);}}
}}
